def filter_by_substring(strings: List[str], substring: str) -> List[str]:
    # Input Validation
    if not strings or not substring:
        return []

    # Filtering Strings
    output_list = []
    for string in strings:
        if substring in string:
            output_list.append(string)

    # Output Generation
    return output_list
